params.command:
$ErrorActionPreference='SilentlyContinue'
$cpu=Get-CimInstance Win32_Processor | Select-Object Name,NumberOfCores,NumberOfLogicalProcessors
$os=Get-CimInstance Win32_OperatingSystem | Select-Object Caption,Version,@{n='FreePhysicalMemoryGB';e={[math]::Round($_.FreePhysicalMemory/1MB,2)}},@{n='TotalVisibleMemoryGB';e={[math]::Round($_.TotalVisibleMemorySize/1MB,2)}}
$disks=Get-CimInstance Win32_LogicalDisk -Filter "DriveType=3" | Select-Object DeviceID,@{n='FreeGB';e={[math]::Round($_.FreeSpace/1GB,1)}},@{n='SizeGB';e={[math]::Round($_.Size/1GB,1)}}
$features=@{}
foreach($f in 'Microsoft-Windows-Subsystem-Linux','VirtualMachinePlatform','Microsoft-Hyper-V-All','Containers'){
  $x=Get-WindowsOptionalFeature -Online -FeatureName $f
  $features[$f]=if($x){$x.State.ToString()}else{'Unavailable'}
}
$wsl = (& wsl.exe -l -v 2>&1 | Out-String).Trim()
$dockerVersion = (& docker version --format '{{json .}}' 2>&1 | Out-String).Trim()
$dockerInfo = (& docker info --format '{{json .}}' 2>&1 | Out-String).Trim()
$dockerPs = (& docker ps -a --format '{{json .}}' 2>&1 | Out-String).Trim()
$compose = (& docker compose version 2>&1 | Out-String).Trim()
$services = if(Test-Path 'C:\HeavenServices'){Get-ChildItem 'C:\HeavenServices' -Force | Select-Object Name,Mode,LastWriteTime}else{@()}
$agentControl = try{Invoke-RestMethod -Uri 'http://127.0.0.1:7331/health' -TimeoutSec 5}catch{$_|Out-String}
[pscustomobject]@{computer=$env:COMPUTERNAME;cpu=$cpu;os=$os;disks=$disks;features=$features;wsl=$wsl;dockerVersion=$dockerVersion;dockerInfo=$dockerInfo;dockerPs=$dockerPs;compose=$compose;heavenServices=$services;agentControl=$agentControl} | ConvertTo-Json -Depth 7 -Compress
